package org.ruoyi.service.lawyer;

import lombok.RequiredArgsConstructor;
import org.ruoyi.common.core.exception.ServiceException;
import org.ruoyi.domain.entity.lawyer.CaseEvent;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;

/** Saved events are the sole timeline source. Every business mutation advances the case revision. */
@Service @RequiredArgsConstructor
public class DossierEventService {
    private final JdbcTemplate jdbc;
    private final TransactionTemplate tx;
    private final DossierAnchorService anchors;
    private final DossierClaimService claims;
    private final DossierReviewAudit audit;
    public record Participant(String subjectId,String label){}
    public record Edit(int expectedVersion,String title,String summary,String eventType,List<Participant> participants,
                       String dateKind,String dateRaw,String dateStart,String dateEnd,String timezone,
                       List<DossierClaimSchema.Link> sources,String reviewStatus,String groupLabel,int sortOrder,String reason){}
    public record Filter(String search,String dateKind,String status,String participant,String fileVersionId,String from,String to,String groupLabel,Integer pageNum,Integer pageSize,String datePool){}
    public record Detail(CaseEvent event,List<DossierClaimSchema.Link> links,List<DossierAnchorService.Resolved> sources,List<DossierReviewAudit.Entry> history,boolean conflict,String revision){}
    public record Listing(List<Detail> rows,long total,long unknownCount,String revision){}
    public record Versioned(Long id,int version){}
    public record Split(int expectedVersion,List<Edit> parts,String reason){}
    public record Merge(List<Versioned> items,Edit result,String reason){}
    public record Group(List<Versioned> items,String groupLabel,String reason){}
    public record Import(List<Versioned> claims,String reason){}
    public record Order(int expectedVersion,Long beforeId,Long afterId,String reason){}
    public record OrderDecision(int expectedVersion,String reason){}
    public record Node(String nodeId,CaseEvent event,List<DossierClaimSchema.Link> sourceRefs,boolean conflict){}
    public record Graph(String revision,List<Node> events,List<Map<String,Object>> precedence){}
    static boolean blank(String s){return s==null||s.isBlank();}
    static String optional(String s){return blank(s)?null:s;}
    static boolean dateConflict(CaseEvent event,List<DossierAnchorService.Resolved> sources){
        if(!"exact".equals(event.getDateKind())||event.getDateStart()==null)return false;
        if(event.getDateRaw().matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")&&!event.getDateRaw().equals(event.getDateStart()))return true;
        var dates=new HashSet<String>();for(var source:sources){var matcher=java.util.regex.Pattern.compile("(?<![0-9])[0-9]{4}-[0-9]{2}-[0-9]{2}(?![0-9])").matcher(source.anchor().getFragmentText());while(matcher.find())dates.add(matcher.group());}
        return !dates.isEmpty()&&!dates.contains(event.getDateStart());
    }
    CaseEvent get(DossierAnchorService.Principal p,Long id,boolean lock){
        anchors.owned(p);
        var rows=jdbc.query("SELECT * FROM lawyer_case_event WHERE id=? AND tenant_id=? AND case_id=? AND user_id=?"+(lock?" FOR UPDATE":""),DossierMaterialService.mapping(CaseEvent.class),id,p.tenantId(),p.caseId(),p.userId());
        if(rows.isEmpty())throw new ServiceException("事件不可用",404);
        return rows.get(0);
    }
    List<DossierClaimSchema.Link> links(DossierAnchorService.Principal p,Long id){return jdbc.query("SELECT CAST(anchor_id AS CHAR),relation FROM lawyer_case_event_source WHERE tenant_id=? AND case_id=? AND event_id=? ORDER BY anchor_id,relation",(r,n)->new DossierClaimSchema.Link(r.getString(1),r.getString(2)),p.tenantId(),p.caseId(),id);}
    void lock(DossierAnchorService.Principal p){
        anchors.owned(p);
        jdbc.update("INSERT IGNORE INTO lawyer_case_timeline_revision(tenant_id,case_id,revision,update_by,update_time) VALUES(?,?,0,?,UTC_TIMESTAMP())",p.tenantId(),p.caseId(),p.userId());
        jdbc.queryForObject("SELECT revision FROM lawyer_case_timeline_revision WHERE tenant_id=? AND case_id=? FOR UPDATE",Long.class,p.tenantId(),p.caseId());
    }
    String revision(DossierAnchorService.Principal p){var rows=jdbc.queryForList("SELECT revision FROM lawyer_case_timeline_revision WHERE tenant_id=? AND case_id=?",Long.class,p.tenantId(),p.caseId());return rows.isEmpty()?"0":rows.get(0).toString();}
    void advance(DossierAnchorService.Principal p){jdbc.update("UPDATE lawyer_case_timeline_revision SET revision=revision+1,update_by=?,update_time=UTC_TIMESTAMP() WHERE tenant_id=? AND case_id=?",p.userId(),p.tenantId(),p.caseId());}
    void record(DossierAnchorService.Principal p,Long id,String action,Object before,Object after,String reason){jdbc.update("INSERT INTO lawyer_case_review_change(id,tenant_id,case_id,object_kind,object_id,action,before_json,after_json,reason,operator_id,create_time) VALUES(?,?,?,'event',?,?,?,?,?,?,UTC_TIMESTAMP())",DossierMaterialService.id(),p.tenantId(),p.caseId(),id,action,BankStatementService.json(before),BankStatementService.json(after),reason,p.userId());}
    static void validate(Edit e){
        if(e==null||e.title()==null||e.title().isBlank()||e.title().length()>300||e.summary()==null||e.summary().length()>5000||e.eventType()==null||!e.eventType().matches("[\\p{L}0-9_-]{1,50}")||e.participants()==null||e.participants().size()>50||e.sources()==null||e.sources().size()>40||e.groupLabel()==null||e.groupLabel().length()>100||Math.abs((long)e.sortOrder())>1_000_000||!Set.of("pending_review","confirmed","excluded").contains(Objects.toString(e.reviewStatus(),"")))throw new ServiceException("事件字段或状态无效",400);
        BankStatementService.reason(e.reason());
        DossierEventDate.validate(e.dateKind(),e.dateRaw(),e.dateStart(),e.dateEnd(),e.timezone());
        for(var participant:e.participants())if(participant==null||participant.label()==null||participant.label().isBlank()||participant.label().length()>100||participant.subjectId()!=null)throw new ServiceException("当前参与主体需填写名称；主体实体关联将在主体模块接入后验证，不接受未核实ID",400);
        for(var source:e.sources()){if(source==null||source.anchorId()==null||!source.anchorId().matches("[1-9][0-9]{0,18}")||!DossierClaimSchema.RELATIONS.contains(Objects.toString(source.relation(),"")))throw new ServiceException("事件来源关联无效",400);try{Long.parseLong(source.anchorId());}catch(Exception ex){throw new ServiceException("来源标识超出范围",400);}}
    }
    void replaceSources(DossierAnchorService.Principal p,Long id,List<DossierClaimSchema.Link> sources){
        jdbc.update("DELETE FROM lawyer_case_event_source WHERE tenant_id=? AND case_id=? AND event_id=?",p.tenantId(),p.caseId(),id);
        for(var link:new LinkedHashSet<>(sources)){anchors.get(p,Long.valueOf(link.anchorId()));jdbc.update("INSERT INTO lawyer_case_event_source(id,tenant_id,case_id,event_id,anchor_id,relation,create_by,create_time) VALUES(?,?,?,?,?,?,?,UTC_TIMESTAMP())",DossierMaterialService.id(),p.tenantId(),p.caseId(),id,Long.valueOf(link.anchorId()),link.relation(),p.userId());}
    }
    Object snapshot(DossierAnchorService.Principal p,CaseEvent e){return Map.of("event",e,"sources",links(p,e.getId()));}
    CaseEvent refresh(DossierAnchorService.Principal p,CaseEvent e,boolean original){
        var errors=claims.sourceErrors(p,links(p,e.getId()),original);
        String source=errors.isEmpty()?"verified":"source_unverified",state=!errors.isEmpty()&&e.getReviewStatus().equals("confirmed")?"stale":e.getReviewStatus(),json=BankStatementService.json(errors);
        if(source.equals(e.getSourceStatus())&&state.equals(e.getReviewStatus())&&json.equals(e.getSourceErrors()))return e;
        return tx.execute(s->{lock(p);var old=get(p,e.getId(),true);if(!old.getVersion().equals(e.getVersion()))return refresh(p,old,original);var before=snapshot(p,old);jdbc.update("UPDATE lawyer_case_event SET source_status=?,source_errors=?,review_status=?,version=version+1,update_by=?,update_time=UTC_TIMESTAMP() WHERE id=? AND version=?",source,json,state,p.userId(),e.getId(),e.getVersion());var after=get(p,e.getId(),false);record(p,e.getId(),"source_dependency",before,snapshot(p,after),"来源材料版本、页文本或原件指纹变化，保留旧确认并要求复核");advance(p);return after;});
    }
    Detail detail(DossierAnchorService.Principal p,Long id,boolean original){var e=refresh(p,get(p,id,false),original);var refs=links(p,id);var sources=new ArrayList<DossierAnchorService.Resolved>();for(var link:refs)try{sources.add(anchors.resolve(p,Long.valueOf(link.anchorId()),original));}catch(ServiceException ignored){}return new Detail(e,refs,sources,audit.history(p,"event",id),refs.stream().anyMatch(l->l.relation().equals("contradicts"))||dateConflict(e,sources),revision(p));}
    public Detail detail(Long caseId,Long id){return detail(anchors.principal(caseId),id,true);}
    public Detail create(Long caseId,Edit e){var p=anchors.principal(caseId);validate(e);return tx.execute(s->{lock(p);return detail(p,insert(p,e,"manual",null),true);});}
    Long insert(DossierAnchorService.Principal p,Edit e,String origin,Long claimId){
        validate(e);var errors=claims.sourceErrors(p,e.sources(),"confirmed".equals(e.reviewStatus()));
        if(e.reviewStatus().equals("confirmed")&&!errors.isEmpty())throw new ServiceException("没有完整有效支持来源，事件不能确认",422);
        long id=DossierMaterialService.id();
        jdbc.update("INSERT INTO lawyer_case_event(id,tenant_id,case_id,user_id,title,summary,event_type,participants_json,date_kind,date_raw,date_start,date_end,timezone,review_status,source_status,source_errors,origin,origin_claim_id,group_label,sort_order,version,reviewer_id,reviewed_at,create_by,create_time,update_by,update_time) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?,IF(?='confirmed',UTC_TIMESTAMP(),NULL),?,UTC_TIMESTAMP(),?,UTC_TIMESTAMP())",id,p.tenantId(),p.caseId(),p.userId(),e.title(),e.summary(),e.eventType(),BankStatementService.json(e.participants()),e.dateKind(),e.dateRaw(),optional(e.dateStart()),optional(e.dateEnd()),optional(e.timezone()),e.reviewStatus(),errors.isEmpty()?"verified":"source_unverified",BankStatementService.json(errors),origin,claimId,e.groupLabel(),e.sortOrder(),e.reviewStatus().equals("confirmed")?p.userId():null,e.reviewStatus(),p.userId(),p.userId());
        replaceSources(p,id,e.sources());record(p,id,"create",Map.of(),snapshot(p,get(p,id,false)),e.reason());advance(p);return id;
    }
    public Detail edit(Long caseId,Long id,Edit e){var p=anchors.principal(caseId);validate(e);return tx.execute(s->{lock(p);update(p,id,e);return detail(p,id,true);});}
    void update(DossierAnchorService.Principal p,Long id,Edit e){
        validate(e);var old=refresh(p,get(p,id,true),true);if(old.getVersion()!=e.expectedVersion())throw new ServiceException("事件版本已变化，保留输入并对照最新版本",409);
        var errors=claims.sourceErrors(p,e.sources(),e.reviewStatus().equals("confirmed"));if(e.reviewStatus().equals("confirmed")&&!errors.isEmpty())throw new ServiceException("没有完整有效支持来源，事件不能确认",422);
        Object before=snapshot(p,old);
        jdbc.update("UPDATE lawyer_case_event SET title=?,summary=?,event_type=?,participants_json=?,date_kind=?,date_raw=?,date_start=?,date_end=?,timezone=?,review_status=?,source_status=?,source_errors=?,group_label=?,sort_order=?,version=version+1,reviewer_id=?,reviewed_at=IF(?='confirmed',UTC_TIMESTAMP(),NULL),update_by=?,update_time=UTC_TIMESTAMP() WHERE id=? AND version=?",e.title(),e.summary(),e.eventType(),BankStatementService.json(e.participants()),e.dateKind(),e.dateRaw(),optional(e.dateStart()),optional(e.dateEnd()),optional(e.timezone()),e.reviewStatus(),errors.isEmpty()?"verified":"source_unverified",BankStatementService.json(errors),e.groupLabel(),e.sortOrder(),e.reviewStatus().equals("confirmed")?p.userId():null,e.reviewStatus(),p.userId(),id,e.expectedVersion());
        replaceSources(p,id,e.sources());record(p,id,e.reviewStatus().equals("excluded")?"exclude":"edit",before,snapshot(p,get(p,id,false)),e.reason());advance(p);
    }
    @SuppressWarnings("unchecked") static List<Participant> participants(CaseEvent e){try{var tree=new com.fasterxml.jackson.databind.ObjectMapper().readTree(e.getParticipantsJson());var out=new ArrayList<Participant>();for(var n:tree)out.add(new Participant(n.path("subjectId").isNull()?null:n.path("subjectId").asText(null),n.path("label").asText()));return out;}catch(Exception ex){throw new ServiceException("参与主体记录损坏，请保留原数据",422);}}
    Edit copy(DossierAnchorService.Principal p,CaseEvent c,String state,String group,String reason){return new Edit(c.getVersion(),c.getTitle(),c.getSummary(),c.getEventType(),participants(c),c.getDateKind(),c.getDateRaw(),c.getDateStart(),c.getDateEnd(),c.getTimezone(),links(p,c.getId()),state,group,c.getSortOrder(),reason);}
    static void batch(List<Versioned> items,int min){if(items==null||items.size()<min||items.size()>100||items.stream().anyMatch(i->i==null||i.id()==null||i.id()<=0||i.version()<1)||items.stream().map(Versioned::id).distinct().count()!=items.size())throw new ServiceException("批量对象/版本范围无效",400);}
    public List<Detail> split(Long caseId,Long id,Split input){var p=anchors.principal(caseId);if(input==null||input.parts()==null||input.parts().size()<2||input.parts().size()>20)throw new ServiceException("拆分需2至20个事件",400);BankStatementService.reason(input.reason());return tx.execute(s->{lock(p);var old=get(p,id,true);if(old.getVersion()!=input.expectedVersion())throw new ServiceException("事件版本冲突",409);var result=new ArrayList<Detail>();for(var part:input.parts()){validate(part);if(!part.reviewStatus().equals("pending_review"))throw new ServiceException("拆分事件必须重新核对",400);result.add(detail(p,insert(p,part,"split",old.getOriginClaimId()),true));}update(p,id,copy(p,old,"excluded",old.getGroupLabel(),input.reason()));record(p,id,"split",Map.of("sourceId",id.toString()),Map.of("newIds",result.stream().map(d->d.event().getId().toString()).toList()),input.reason());return result;});}
    public Detail merge(Long caseId,Merge input){var p=anchors.principal(caseId);if(input==null)throw new ServiceException("缺少合并对象",400);batch(input.items(),2);validate(input.result());BankStatementService.reason(input.reason());if(!input.result().reviewStatus().equals("pending_review"))throw new ServiceException("合并事件必须重新核对",400);return tx.execute(s->{lock(p);var all=new ArrayList<CaseEvent>();var refs=new LinkedHashSet<DossierClaimSchema.Link>();for(var item:input.items()){var c=get(p,item.id(),true);if(c.getVersion()!=item.version())throw new ServiceException("合并事件版本冲突",409);all.add(c);refs.addAll(links(p,c.getId()));}refs.addAll(input.result().sources());var e=input.result();var combined=new Edit(1,e.title(),e.summary(),e.eventType(),e.participants(),e.dateKind(),e.dateRaw(),e.dateStart(),e.dateEnd(),e.timezone(),new ArrayList<>(refs),"pending_review",e.groupLabel(),e.sortOrder(),input.reason());var id=insert(p,combined,"merge",null);for(var c:all)update(p,c.getId(),copy(p,c,"excluded",c.getGroupLabel(),input.reason()));record(p,id,"merge",Map.of("sourceIds",all.stream().map(c->c.getId().toString()).toList()),snapshot(p,get(p,id,false)),input.reason());return detail(p,id,true);});}
    public List<Detail> group(Long caseId,Group input){var p=anchors.principal(caseId);if(input==null||input.groupLabel()==null||input.groupLabel().length()>100)throw new ServiceException("分组无效",400);batch(input.items(),1);BankStatementService.reason(input.reason());return tx.execute(s->{lock(p);var out=new ArrayList<Detail>();for(var item:input.items()){var c=get(p,item.id(),true);if(c.getVersion()!=item.version())throw new ServiceException("分组事件版本冲突",409);var before=snapshot(p,c);jdbc.update("UPDATE lawyer_case_event SET group_label=?,version=version+1,update_by=?,update_time=UTC_TIMESTAMP() WHERE id=? AND version=?",input.groupLabel(),p.userId(),c.getId(),item.version());record(p,c.getId(),"group",before,snapshot(p,get(p,c.getId(),false)),input.reason());advance(p);out.add(detail(p,c.getId(),false));}return out;});}
    public List<Detail> fromClaims(Long caseId,Import input){var p=anchors.principal(caseId);if(input==null)throw new ServiceException("缺少候选对象",400);batch(input.claims(),1);BankStatementService.reason(input.reason());return tx.execute(s->{lock(p);var out=new ArrayList<Detail>();for(var item:input.claims()){var c=claims.refresh(p,claims.get(p,item.id(),true),true);if(c.getVersion()!=item.version())throw new ServiceException("候选版本已变化，请刷新后选择",409);if(c.getReviewStatus().equals("excluded"))throw new ServiceException("已排除候选不能自动加入时间线，请先明确恢复候选",422);var existing=jdbc.queryForList("SELECT id FROM lawyer_case_event WHERE tenant_id=? AND case_id=? AND origin_claim_id=?",Long.class,p.tenantId(),p.caseId(),c.getId());if(!existing.isEmpty()){out.add(detail(p,existing.get(0),false));continue;}var values=DossierClaimService.values(c);String raw=Objects.toString(values.get("dateRaw"),""),kind=DossierEventDate.inferredKind(raw);if(kind.equals("exact"))kind="approximate";String start=raw.matches("[0-9]{4}(?:-[0-9]{2}(?:-[0-9]{2})?)?")?raw:null;if(start!=null)try{DossierEventDate.partial(start);}catch(ServiceException ex){start=null;kind="unknown";}var e=new Edit(1,c.getClaimText().substring(0,Math.min(300,c.getClaimText().length())),c.getClaimText(),"fact",blank(values.get("name"))?List.of():List.of(new Participant(null,values.get("name"))),kind,raw,start,null,null,claims.linkValues(p,c.getId()),"pending_review","",0,input.reason());out.add(detail(p,insert(p,e,"from_claim",c.getId()),false));}return out;});}
    public Listing list(Long caseId,Filter f){var p=anchors.principal(caseId);var selected=selected(p,f);int page=Math.max(1,f==null||f.pageNum()==null?1:f.pageNum()),size=Math.min(100,Math.max(1,f==null||f.pageSize()==null?25:f.pageSize()));long unknown=selected.stream().filter(e->e.getDateStart()==null&&!e.getReviewStatus().equals("excluded")).count();return new Listing(selected.stream().skip((long)(page-1)*size).limit(size).map(e->detail(p,e.getId(),false)).toList(),selected.size(),unknown,revision(p));}
    List<CaseEvent> selected(DossierAnchorService.Principal p,Filter f){
        var all=jdbc.query("SELECT * FROM lawyer_case_event WHERE tenant_id=? AND case_id=? AND user_id=? ORDER BY id",DossierMaterialService.mapping(CaseEvent.class),p.tenantId(),p.caseId(),p.userId());if(all.size()>5000)throw new ServiceException("单案事件超过5000，请分案整理",422);
        var from=f==null?null:DossierEventDate.partial(optional(f.from()));var to=f==null?null:DossierEventDate.partial(optional(f.to()));
        return all.stream().map(e->refresh(p,e,false)).filter(e->f==null||((blank(f.search())||(e.getTitle()+" "+e.getSummary()+" "+e.getDateRaw()).toLowerCase(Locale.ROOT).contains(f.search().toLowerCase(Locale.ROOT)))&&(blank(f.status())||e.getReviewStatus().equals(f.status()))&&(blank(f.dateKind())||e.getDateKind().equals(f.dateKind()))&&(blank(f.groupLabel())||e.getGroupLabel().equals(f.groupLabel()))&&(blank(f.datePool())||f.datePool().equals("unknown")&&e.getDateStart()==null&&!e.getReviewStatus().equals("excluded")||f.datePool().equals("known")&&e.getDateStart()!=null)&&(blank(f.participant())||participants(e).stream().anyMatch(v->v.label().contains(f.participant())))&&(blank(f.fileVersionId())||links(p,e.getId()).stream().anyMatch(l->anchors.get(p,Long.valueOf(l.anchorId())).getFileVersionId().toString().equals(f.fileVersionId())))&&((from==null&&to==null)||e.getDateStart()!=null&&(from==null||DossierEventDate.partial(Objects.toString(e.getDateEnd(),e.getDateStart())).end().compareTo(from.start())>=0)&&(to==null||DossierEventDate.partial(e.getDateStart()).start().compareTo(to.end())<=0)))).sorted(Comparator.<CaseEvent,String>comparing(e->e.getDateStart()==null?"9999-99-99":DossierEventDate.partial(e.getDateStart()).start().toString()).thenComparing(CaseEvent::getSortOrder).thenComparing(CaseEvent::getId)).toList();
    }
    public Graph graph(Long caseId,Filter f){var p=anchors.principal(caseId);return tx.execute(s->{lock(p);var sourceCache=new HashMap<String,DossierAnchorService.Resolved>();var events=selected(p,f).stream().filter(e->!e.getReviewStatus().equals("excluded")).map(e->{var refs=links(p,e.getId());var resolved=new ArrayList<DossierAnchorService.Resolved>();for(var ref:refs)try{resolved.add(sourceCache.computeIfAbsent(ref.anchorId(),key->anchors.resolve(p,Long.valueOf(key),false)));}catch(ServiceException ignored){}return new Node("event:"+e.getId(),e,refs,refs.stream().anyMatch(l->l.relation().equals("contradicts"))||dateConflict(e,resolved));}).toList();var ids=new HashSet<>(events.stream().map(d->d.event().getId().toString()).toList());return new Graph(revision(p),events,orders(p).stream().filter(row->ids.contains(row.get("beforeId"))&&ids.contains(row.get("afterId"))).toList());});}
    List<Map<String,Object>> orders(DossierAnchorService.Principal p){return jdbc.queryForList("SELECT CAST(id AS CHAR) id,CAST(before_event_id AS CHAR) beforeId,CAST(after_event_id AS CHAR) afterId,state,version,reason FROM lawyer_case_event_precedence WHERE tenant_id=? AND case_id=? AND state='draft' ORDER BY id",p.tenantId(),p.caseId());}
    public Graph order(Long caseId,Order input){var p=anchors.principal(caseId);if(input==null||input.beforeId()==null||input.afterId()==null||input.beforeId().equals(input.afterId()))throw new ServiceException("草稿先后关系无效",400);BankStatementService.reason(input.reason());return tx.execute(s->{lock(p);var before=get(p,input.beforeId(),true);var after=get(p,input.afterId(),true);if(before.getReviewStatus().equals("excluded")||after.getReviewStatus().equals("excluded"))throw new ServiceException("排除事件不能加入先后草稿",422);if(before.getVersion()!=input.expectedVersion())throw new ServiceException("事件版本冲突",409);var graph=new HashMap<String,List<String>>();for(var edge:orders(p))graph.computeIfAbsent(edge.get("beforeId").toString(),k->new ArrayList<>()).add(edge.get("afterId").toString());var queue=new ArrayDeque<String>();var seen=new HashSet<String>();queue.add(input.afterId().toString());while(!queue.isEmpty()){var id=queue.remove();if(id.equals(input.beforeId().toString()))throw new ServiceException("草稿先后关系形成环，请检查矛盾",422);if(seen.add(id))queue.addAll(graph.getOrDefault(id,List.of()));}if(graph.getOrDefault(input.beforeId().toString(),List.of()).contains(input.afterId().toString()))return graph(caseId,null);long id=DossierMaterialService.id();jdbc.update("INSERT INTO lawyer_case_event_precedence(id,tenant_id,case_id,before_event_id,after_event_id,state,version,reason,create_by,create_time,update_by,update_time) VALUES(?,?,?,?,?,'draft',1,?,?,UTC_TIMESTAMP(),?,UTC_TIMESTAMP())",id,p.tenantId(),p.caseId(),input.beforeId(),input.afterId(),input.reason(),p.userId(),p.userId());record(p,input.beforeId(),"order_draft",Map.of(),Map.of("edgeId",Long.toString(id),"beforeId",input.beforeId().toString(),"afterId",input.afterId().toString(),"state","draft"),input.reason());advance(p);return graph(caseId,null);});}
    public void excludeOrder(Long caseId,Long edgeId,OrderDecision input){var p=anchors.principal(caseId);if(input==null)throw new ServiceException("缺少草稿版本",400);BankStatementService.reason(input.reason());tx.executeWithoutResult(s->{lock(p);var rows=jdbc.queryForList("SELECT * FROM lawyer_case_event_precedence WHERE tenant_id=? AND case_id=? AND id=? FOR UPDATE",p.tenantId(),p.caseId(),edgeId);if(rows.isEmpty())throw new ServiceException("关系草稿不可用",404);var edge=rows.get(0);if(!edge.get("state").equals("draft")||((Number)edge.get("version")).intValue()!=input.expectedVersion())throw new ServiceException("关系草稿版本冲突",409);jdbc.update("UPDATE lawyer_case_event_precedence SET state='excluded',version=version+1,update_by=?,update_time=UTC_TIMESTAMP() WHERE id=?",p.userId(),edgeId);record(p,((Number)edge.get("before_event_id")).longValue(),"order_exclude",edge,Map.of("edgeId",edgeId.toString(),"state","excluded"),input.reason());advance(p);});}
}
